// Generated by the Salvo compiler: the actor scheduler's host layer. The
// scheduler itself is Salvo — `std/runtime.sv`'s core and the routing service
// `std/runtime/routing.sv` (RUNTIME.md), written once for both backends — and
// this file is what generated code and host code call: the entry points they
// always called, each a thin shim onto those, plus a registry of what only
// generated code knows (decoders, control builders, outbound hooks).
//
// The registry is concurrent maps; it is never held across a call into the core
// or the routing service.
// The mirror of the Rust backend's `scheduler.rs`.
package salvo

import salvo.platform.runtime.Dyn
import salvo.platform.runtime.Body

interface SalvoActor {
    /** A user message (a `send fn` invocation). */
    fun handle(ctx: SalvoCtx, msg: Any?)

    /** A reply delivery: the slot names the parked continuation. */
    fun resume(ctx: SalvoCtx, slot: Long, value: Any?)

    /**
     * [addr-routable] [wire-format] Decodes a reply that arrived over the
     * wire for the continuation parked at [slot]: only the actor knows the
     * answer's type. `null` when nothing is parked there or the bytes are
     * malformed. The `Boolean` half says whether a value was decoded at all,
     * since `null` is itself a value (`None`).
     */
    fun decodeReply(slot: Long, payload: ByteArray): Pair<Boolean, Any?> = Pair(false, null)
}

/**
 * [addr-routable] The routable identity of an actor: the node hosting it, its
 * index there, and the unguessable bits minted at its spawn [addr-capability].
 */
data class SalvoRemoteRef(val node: Long, val actor: Long, val bits: Long)

/** Passed to every activation: the actor's own identity. */
class SalvoCtx(val addr: Int)

/** [addr-routable] A reply that arrived over the wire, still as bytes. */
private class SalvoRawReply(val bytes: ByteArray)

object SalvoSched {
    /** [main-pool] The pool main is the single worker of. */
    const val MAIN_POOL = 0

    // ---- the local surface: shims onto the core

    /** [threadsafe-platform] A host thread that may inject work is open… */
    fun externalBegin() = salvo.runtime.externalBegin()

    /** …and is gone. */
    fun externalEnd() = salvo.runtime.externalEnd()

    fun currentPool(): Int = salvo.platform.runtime.herePool()

    fun pool(n: Int): Int = poolWithSink(n, null, null)

    /** [pool-fault-sink] A pool whose uncaught faults go to [sinkAddr], as the message [sinkBuild] makes. */
    fun poolWithSink(n: Int, sinkAddr: Int?, sinkBuild: ((String) -> Any?)?): Int {
        if (sinkAddr != null && sinkBuild != null) sinks[sinkAddr] = sinkBuild
        val pool = salvo.runtime.newPoolOf(n, sinkAddr ?: -1)
        salvo.runtime.routing.adopt(pool)
        return pool
    }

    /** [waitfor-dedicated] A pool of exactly one thread. */
    fun thread(): Int {
        // [pool-retire] Its thread returns once its actor is dead.
        val pool = salvo.runtime.newDedicatedPool()
        salvo.runtime.routing.adopt(pool)
        return pool
    }

    /** Spawns an actor on a pool. The queue bound is explicit and required. */
    fun spawn(
        pool: Int,
        bound: Int,
        body: SalvoActor,
        decode: ((String, ByteArray) -> Pair<Boolean, Any?>)? = null,
    ): Int {
        val addr = salvo.runtime.spawnBody(pool, bound, bodyOf(body))
        if (decode != null) decoders[addr] = decode
        return addr
    }

    /** The core's body for a generated actor: 0 a message, 1 an answer, 2 a fault report for a sink. */
    private fun bodyOf(actor: SalvoActor): Body =
        Body { kind, slot, value ->
            val ctx = SalvoCtx(salvo.platform.runtime.hereActor())
            when (kind) {
                0 -> actor.handle(ctx, value.v)
                1 -> {
                    val v = value.v
                    if (v is SalvoRawReply) {
                        val (ok, decoded) = actor.decodeReply(slot, v.bytes)
                        if (ok) actor.resume(ctx, slot, decoded)
                    } else {
                        actor.resume(ctx, slot, v)
                    }
                }
                else -> {
                    val build = sinks[ctx.addr]
                    if (build != null) actor.handle(ctx, build(value.v as String))
                }
            }
        }

    /** Sends a user message: waits while the mailbox is full; to the dead, a no-op. */
    fun send(addr: Int, msg: Any?) {
        salvo.runtime.sendDyn(addr, Dyn(msg))
    }

    fun mint(addr: Int): Pair<SalvoReply, Long> {
        val t = salvo.runtime.mint(addr, false)
        return Pair(SalvoReply(t), t.slot)
    }

    fun mintGated(addr: Int): Pair<SalvoReply, Long> {
        val t = salvo.runtime.mint(addr, true)
        return Pair(SalvoReply(t), t.slot)
    }

    /** [task-mint] A token whose answer schedules [body] on [pool]. */
    fun mintTask(
        pool: Int,
        decode: (ByteArray) -> Pair<Boolean, Any?> = { _ -> Pair(false, null) },
        body: (Any?) -> Unit,
    ): SalvoReply {
        var once: ((Any?) -> Unit)? = body
        val b = Body { _, _, value ->
            val f = once
            once = null
            f?.invoke(value.v)
        }
        return SalvoReply(salvo.runtime.mintTaskOn(pool, b)).also { it.decode = decode }
    }

    /** [actor-watch] A death watch: the core answers it with an `Exit`. */
    fun watch(addr: Int, onExit: SalvoReply, exit: (String) -> Any?) {
        onExit.takeLocal()?.let { salvo.runtime.watch(addr, it) }
    }

    /** [actor-on-idle] A quiescence hook: the core answers it with an `Idle`. */
    fun onIdle(pool: Int, notify: SalvoReply, idle: (Int, Int) -> Any?) {
        notify.takeLocal()?.let { salvo.runtime.onIdle(pool, it) }
    }

    /** A waiter: the `waitfor` bridge. Answers (token, waiter id). */
    fun waiter(): Pair<SalvoReply, Int> {
        val m = salvo.runtime.waiter()
        return Pair(SalvoReply(m.token), m.wid)
    }

    /** [waitfor-pump] Waits for the answer, serving this thread's pool meanwhile. */
    fun awaitReply(wid: Int): Any? = salvo.runtime.awaitAnswer(wid).v

    // ---- across machines
    //
    // The routing itself — identities, proxies, credits, routes and the
    // frames, in the canonical encoding — is the Salvo service
    // `runtime.routing` (`std/runtime/routing.sv`). What stays here is what
    // only generated code knows, registered by index: each actor's message
    // decoder, each waiting frame's and exported task's answer decoder, each
    // control sink's message builder and each node's outbound hook. The
    // service reaches them through its platform fns
    // (`std/platform/runtime/routing.kt`).

    internal val sinks = java.util.concurrent.ConcurrentHashMap<Int, (String) -> Any?>()
    internal val decoders = java.util.concurrent.ConcurrentHashMap<Int, (String, ByteArray) -> Pair<Boolean, Any?>>()
    internal val waiterDecoders = java.util.concurrent.ConcurrentHashMap<Int, (ByteArray) -> Pair<Boolean, Any?>>()
    internal val taskDecoders = java.util.concurrent.ConcurrentHashMap<Long, (ByteArray) -> Pair<Boolean, Any?>>()
    internal val controls = java.util.concurrent.ConcurrentHashMap<Int, (Long, ByteArray) -> Any?>()
    internal val wires = java.util.concurrent.ConcurrentHashMap<Long, (ByteArray, ByteArray) -> Unit>()

    fun nodeId(): Long = hereNode()

    fun hereNode(): Long = salvo.runtime.routing.hereNode()

    fun newNode(): Long = salvo.runtime.routing.newNode()

    fun poolAt(node: Long, n: Int): Int = salvo.runtime.routing.poolAt(node, n)

    fun addrIdentity(addr: Int): SalvoRemoteRef {
        val r = salvo.runtime.routing.identity(addr)
        return SalvoRemoteRef(r.node, r.actor, r.bits)
    }

    fun sameActor(a: Int, b: Int): Boolean = salvo.runtime.routing.sameActor(a, b)

    fun importAddr(r: SalvoRemoteRef): Int = salvo.runtime.routing.importAddr(r.node, r.actor, r.bits)

    fun isRemote(addr: Int): Boolean = salvo.runtime.routing.remote(addr)

    fun addRoute(node: Long, endpoint: ByteArray) = salvo.runtime.routing.route(node, SalvoBytes(endpoint))

    /** [net-connect] Whether the current node's outbound hook is bound. */
    fun connected(): Boolean = salvo.runtime.routing.connected()

    fun setWire(hook: (ByteArray, ByteArray) -> Unit) {
        wires[hereNode()] = hook
        salvo.runtime.routing.outboundBound()
    }

    /** [addr-routable] [wire-format] The typed send; for a proxy, encoded here and routed. */
    fun <M> sendWire(addr: Int, msg: M, proto: String, codec: WireCodec<M>) {
        // The core hands the message back when the addr is a proxy.
        val back = salvo.runtime.sendOrBack(addr, Dyn(msg)) ?: return
        @Suppress("UNCHECKED_CAST")
        val m = back.v as M
        val out = WireOut()
        codec.enc(m, out)
        salvo.runtime.routing.sendRemote(addr, proto, out.toBytes())
    }

    fun credits(addr: Int): Int? = salvo.runtime.routing.credits(addr)

    /** [addr-routable] [wire-format] The typed reply. */
    fun <T> replyWire(reply: SalvoReply, value: T, codec: WireCodec<T>) {
        val parts = reply.remote
        if (parts == null) {
            reply.send(value)
            return
        }
        val out = WireOut()
        codec.enc(value, out)
        salvo.runtime.routing.answerRemote(parts, out.toBytes())
    }

    /** [addr-routable] The wire form of a reply token. Exporting a task moves its body aside. */
    fun replyExport(reply: SalvoReply): salvo.runtime.routing.ReplyParts {
        reply.remote?.let { return it }
        val tok = reply.takeLocal() ?: return salvo.runtime.routing.ReplyParts(0, 0, 0, 0, 0)
        val parts = salvo.runtime.routing.exportReply(salvo.runtime.exportToken(tok))
        if (parts.kind == 2) taskDecoders[parts.id] = reply.decode
        return parts
    }

    /** [addr-routable] A reply token decoded from the wire. */
    fun replyImport(parts: salvo.runtime.routing.ReplyParts): SalvoReply {
        val here = hereNode()
        return when {
            parts.node == here && parts.kind == 0 -> SalvoReply(salvo.runtime.tokenToActor(parts.id.toInt(), parts.slot))
            parts.node == here && parts.kind == 1 -> SalvoReply(salvo.runtime.tokenToWaiter(parts.id.toInt(), parts.slot))
            else -> SalvoReply(null).also { it.remote = parts }
        }
    }

    fun waiterDecoder(wid: Int, decode: (ByteArray) -> Pair<Boolean, Any?>) {
        waiterDecoders[wid] = decode
    }

    fun setProtocols(table: List<Pair<String, String>>) = salvo.runtime.routing.registerProtocols(table)

    fun localProtocols(): List<Pair<String, String>> = salvo.runtime.routing.localProtocols()

    fun setPeerProtocols(node: Long, table: List<Pair<String, String>>) = salvo.runtime.routing.setPeerProtocols(node, table)

    fun peerProtocol(node: Long, protocol: String): String? = salvo.runtime.routing.peerProtocol(node, protocol)

    fun watchControl(channel: String, sink: Int, build: (Long, ByteArray) -> Any?) {
        controls[sink] = build
        salvo.runtime.routing.watchControl(channel, sink)
    }

    /** [node-group] A CONTROL frame for whichever node receives it: a HELLO's. */
    fun controlFrame(channel: String, payload: ByteArray): ByteArray =
        salvo.runtime.routing.controlFrame(channel, SalvoBytes(payload)).toByteArray()

    fun sendControl(to: Long, channel: String, payload: ByteArray) =
        salvo.runtime.routing.sendControl(to, channel, SalvoBytes(payload))

    fun nodeLeft(node: Long) = salvo.runtime.routing.nodeLeft(node)

    fun pending(addr: Int): Int = salvo.runtime.routing.pending(addr)

    /** [route-stub] The replica [group] mirrors its member set: the routing service keeps it. */
    fun viewSet(group: Int, members: List<Int>) = salvo.runtime.routing.viewSet(group, members)

    /** [route-stub] The mirrored members of [group], by (node, actor id). */
    fun viewMembers(group: Int): List<Int> = salvo.runtime.routing.viewMembers(group)

    /** [route-stub] FNV-1a over the key's canonical bytes, identical to Rust's `salvo_key_hash`. */
    fun keyHash(bytes: ByteArray): Long {
        var h = -3750763034362895579L // 0xcbf29ce484222325
        for (b in bytes) {
            h = h xor (b.toLong() and 0xff)
            h *= 1099511628211L
        }
        return h
    }

    /** [addr-routable] An answer that arrived over the wire for an actor, still as bytes. */
    fun rawAnswer(payload: ByteArray): Dyn = Dyn(SalvoRawReply(payload))

    fun deliverFrame(frame: ByteArray): Boolean = salvo.runtime.routing.deliver(SalvoBytes(frame))
}

/**
 * A one-shot reply capability: a token of the core's, or one minted on
 * another node and decoded here. `send` delivers exactly once — the guarantee
 * is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(private var token: salvo.runtime.Token?) {
    /** [addr-routable] For a token minted elsewhere: (node, kind, id, slot, bits). */
    internal var remote: salvo.runtime.routing.ReplyParts? = null

    /** [wire-format] How a task's answer is decoded should it return over the wire. */
    internal var decode: (ByteArray) -> Pair<Boolean, Any?> = { _ -> Pair(false, null) }

    /** [platform-check] What a platform adapter checks of the value the host sends. */
    internal var check: ((Any?) -> Any?)? = null

    internal fun takeLocal(): salvo.runtime.Token? =
        synchronized(this) {
            val t = token
            token = null
            t
        }

    fun checked(f: (Any?) -> Any?): SalvoReply {
        check = f
        return this
    }

    fun send(value: Any?) {
        val f = check
        val v = if (f != null) f(value) else value
        val t = takeLocal() ?: error("internal: an untyped reply to a remote token")
        salvo.runtime.answer(t, Dyn(v))
    }

    /**
     * [platform-reply] Hands the token to host code that completes it later,
     * from any thread; until then the scheduler counts one outside source of
     * work, so a frame waiting on it is neither idle nor deadlocked. An unsent
     * host reply is not detected on this backend (the JVM has no drop).
     */
    fun hosted(): SalvoHostReply {
        salvo.runtime.externalBegin()
        return SalvoHostReply(this)
    }
}

/** [platform-reply] A reply the host has taken on: [send] completes it once, from any thread. */
class SalvoHostReply internal constructor(private val reply: SalvoReply) {
    private val sent = java.util.concurrent.atomic.AtomicBoolean(false)

    fun send(value: Any?) {
        check(sent.compareAndSet(false, true)) { "salvo: a host reply was sent twice [platform-reply]" }
        if (reply.remote != null) {
            error("salvo: a host-completed reply to a token minted on another node is not supported yet [platform-reply]")
        }
        reply.send(value)
        salvo.runtime.externalEnd()
    }
}

// [addr-routable] The codecs of the two scheduler handles live here, beside
// what they ask, so the wire stands alone in a program with no actors.
/** [addr-routable] An `Addr<E>` is a scheduler index; on the wire its routable identity, 24 bytes. */
object AddrCodec : WireCodec<Int> {
    override fun enc(v: Int, out: WireOut) {
        val r = SalvoSched.addrIdentity(v)
        out.i64(r.node); out.i64(r.actor); out.i64(r.bits)
    }
    override fun dec(inp: WireIn): Int = SalvoSched.importAddr(SalvoRemoteRef(inp.i64(), inp.i64(), inp.i64()))
}

/** [addr-routable] A `Reply<T>` on the wire: `(node, kind, id, slot, bits)`, 33 bytes. */
object ReplyCodec : WireCodec<SalvoReply> {
    override fun enc(v: SalvoReply, out: WireOut) {
        val e = SalvoSched.replyExport(v)
        out.i64(e.node); out.u8(e.kind); out.i64(e.id); out.i64(e.slot); out.i64(e.bits)
    }
    override fun dec(inp: WireIn): SalvoReply {
        val node = inp.i64(); val kind = inp.u8(); val id = inp.i64(); val slot = inp.i64(); val bits = inp.i64()
        return SalvoSched.replyImport(salvo.runtime.routing.ReplyParts(node, kind, id, slot, bits))
    }
}
